head.script:
scwin.onpageload = function() {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
};
scwin.onpageunload = function() {};
scwin.openPopup = function(url, opt, dataObj) {
    var _dataObj = dataObj || {};
    var _width = opt.width || '500px';
    var _height = opt.height || '500px';
    var _left = (document.body.offsetWidth / 2) -
        (parseInt(parseInt(_width)) / 2) + 'px';
    var _top = (document.body.offsetHeight / 2) -
        (parseInt(parseInt(_height)) / 2) + 'px';
    var options = {
        id: opt.id,
        type: opt.type || "litewindow",
        width: opt.width || "500px",
        height: opt.height || "500px",
        top: opt.top || _top || "140px",
        left: opt.left || _left || "500px",
        popupName: opt.popupName || '',
        modal: opt.modal || true,
        useIFrame: opt.useIFrame || false,
        title: opt.title || false,
        frameMode: opt.frameMode || "iframe",
        dataObject: _dataObj,
        // litewindow 에서 사용 가능 기능.
        className: opt.className,
        useControl: opt.useControl || true,
        foldOnMinimized: opt.foldOnMinimized || true
        //, alwaysOnTop : opt.alwaysOnTop || false
        //, useModalStack: opt.useModalStack || true 
    };
    console.log(options);
    //console.log(scopeObj);
    $p.openPopup(url, options);
};
scwin.btn_field_onclick = function(type) {
    var fieldInfo = {
        type: "json",
        data: {
            "field": dma_field.getJSON(),
            callbackSelectFn: $p.id + "scwin.callbackSelectFieldFunc"
        },
        name: "fieldInfo"
    };
    //		if( type != 1 && type !=2 ){
    //			fieldInfo.data.field = dma_field.getJSON()
    //		}
    //		else 
    if (type == 1) {
        fieldInfo.data.field.FIELD_ID = inp_fieldId.getValue();
        fieldInfo.data.field.FIELD_NM = "";
    } else if (type == 2) {
        fieldInfo.data.field.FIELD_ID = ""
        fieldInfo.data.field.FIELD_NM = inp_fieldNm.getValue();
    }
    var opt = {
        id: "fieldPop",
        popupName: "현장선택",
        width: "600px",
        height: "450px",
        frameMode: "wframe",
        className: "w600"
    };
    scwin.openPopup("/2019/lgsni/xml/popup/popup1.xml", opt, fieldInfo);
};
scwin.callbackSelectFieldFunc = function(rowData) {
    dma_field.setJSON(rowData);
    //scwin.btn_sch_onclick();
};
scwin.btn_sch_onclick = function(e) {
    var FIELD_id = dma_field.get('FIELD_ID');
    scwin.mode = "S";
    $p.executeSubmission(sbm_search);
};
scwin.sbm_search_submitdone = function(e) {
    var _options = {
        closeGroup: false
    };
    scwin.setGridGroupby(_options);
};
